package com.match.course.web;
import com.match.course.model.CourseTrainingReportRequest; import com.match.course.service.CourseTrainingReportService; import com.match.security.RoleGuard; import com.match.util.result.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/user/course-reports") public class CourseTrainingReportController { private final RoleGuard roles; private final CourseTrainingReportService service; public CourseTrainingReportController(RoleGuard roles,CourseTrainingReportService service){this.roles=roles;this.service=service;} @GetMapping("/{courseId}") public ResponseResult<Object> get(@PathVariable String courseId){return Response.makeOKRsp(service.get(roles.requireBusinessUser().getUserId(),courseId));} @PutMapping("/{courseId}") public ResponseResult<Object> save(@PathVariable String courseId,@RequestBody CourseTrainingReportRequest request){return Response.makeOKRsp(service.save(roles.requireBusinessUser().getUserId(),courseId,request==null?"":request.getContent()));} }
